import { describe, expect, it } from "vitest";

import type { ChartTheme } from "@/lib/echarts";

import { buildLineOption } from "./LineChart";

const theme: ChartTheme = {
  textColor: "black",
  mutedTextColor: "gray",
  faintTextColor: "silver",
  axisColor: "rule",
  surfaceColor: "white",
  primaryColor: "gold",
  palette: ["gold", "kinpaku", "green", "danger"],
  tokenColors: {
    "--ks-primary": "gold",
    "--ks-kinpaku": "kinpaku",
    "--ks-success": "green",
    "--ks-danger": "danger",
  },
};

function getSeries(option: ReturnType<typeof buildLineOption>) {
  return option.series as Array<Record<string, unknown>>;
}

describe("buildLineOption", () => {
  it("builds labeled line series with resolved colors, area, dots, and grid", () => {
    const option = buildLineOption(
      [
        { label: "Revenue", data: [-2, 4, 8], color: "var(--ks-primary)" },
        { label: "Cost", data: [1, 3, 5] },
      ],
      ["Jan", "Feb", "Mar"],
      { showArea: true, showDots: true, showGrid: true, theme }
    );

    expect(option.xAxis).toEqual(
      expect.objectContaining({
        type: "category",
        data: ["Jan", "Feb", "Mar"],
        axisLabel: expect.objectContaining({ show: true, color: "silver", fontSize: 10 }),
      })
    );
    expect(option.yAxis).toEqual(
      expect.objectContaining({
        type: "value",
        min: -2,
        max: 8,
        splitNumber: 4,
        splitLine: expect.objectContaining({ show: true }),
      })
    );
    expect(getSeries(option)).toEqual([
      expect.objectContaining({
        name: "Revenue",
        type: "line",
        data: [-2, 4, 8],
        symbol: "circle",
        symbolSize: 6,
        lineStyle: { color: "gold", width: 2, join: "round" },
        itemStyle: { color: "gold" },
        areaStyle: { color: "gold", opacity: 0.12 },
      }),
      expect.objectContaining({
        name: "Cost",
        data: [1, 3, 5],
        lineStyle: { color: "kinpaku", width: 2, join: "round" },
        itemStyle: { color: "kinpaku" },
      }),
    ]);
  });

  it("keeps the chart unfilled and hides dots and grid when disabled", () => {
    const option = buildLineOption([{ label: "Series", data: [2, 4], color: "#123456" }], undefined, {
      showArea: false,
      showDots: false,
      showGrid: false,
      theme,
    });

    expect(option.xAxis).toEqual(
      expect.objectContaining({
        data: ["0", "1"],
        axisLabel: expect.objectContaining({ show: false }),
      })
    );
    expect(option.yAxis).toEqual(
      expect.objectContaining({
        splitLine: expect.objectContaining({ show: false }),
      })
    );
    expect(getSeries(option)[0]).toEqual(
      expect.objectContaining({
        symbol: "none",
        areaStyle: undefined,
        itemStyle: { color: "#123456" },
      })
    );
  });

  it("attaches a markLine reference line to the first series and applies step interpolation", () => {
    const option = buildLineOption(
      [
        { label: "A", data: [1, 2], color: "#123456" },
        { label: "B", data: [3, 4], color: "#654321" },
      ],
      undefined,
      {
        showArea: false,
        showDots: false,
        showGrid: false,
        referenceLine: { value: 5, label: "Meta: 5" },
        step: "middle",
        theme,
      }
    );

    const series = getSeries(option);
    expect(series[0]).toEqual(
      expect.objectContaining({
        step: "middle",
        markLine: expect.objectContaining({
          silent: true,
          symbol: "none",
          data: [{ yAxis: 5 }],
          label: expect.objectContaining({ show: true, formatter: "Meta: 5" }),
        }),
      })
    );
    // markLine so vai na primeira serie, pra nao duplicar a linha no grafico
    expect(series[1].markLine).toBeUndefined();
    expect(series[1].step).toBe("middle");
  });

  it("omits the reference line when none is provided", () => {
    const option = buildLineOption([{ label: "A", data: [1, 2] }], undefined, {
      showArea: false,
      showDots: false,
      showGrid: false,
      theme,
    });
    expect(getSeries(option)[0].markLine).toBeUndefined();
  });
});

import type React from 'react'

export interface LineChartSeries {
  label: string
  data: number[]
  color?: string
}

/** Linha horizontal de meta/media com rotulo (ex.: "Meta: 80"). */
export interface LineChartReferenceLine {
  value: number
  label?: string
  color?: string
}

/** Interpolacao em degrau nativa do ECharts (line series `step`), em vez de reta entre pontos. */
export type LineChartStep = 'start' | 'middle' | 'end'

export interface LineChartProps {
  series: LineChartSeries[]
  labels?: string[]
  height?: number
  width?: number | string
  showArea?: boolean
  showDots?: boolean
  showGrid?: boolean
  showLegend?: boolean
  /** Linha horizontal de meta/media com rotulo, desenhada via markLine nativo do ECharts. */
  referenceLine?: LineChartReferenceLine
  /** Interpolacao em degrau (nativa do ECharts) em vez de reta entre pontos. */
  step?: LineChartStep
  className?: string
  style?: React.CSSProperties
}

"use client";

import type { EChartsOption, MarkLineComponentOption } from "echarts";
import { LineChart as EChartsLineChart } from "echarts/charts";
import { GridComponent, MarkLineComponent, TooltipComponent } from "echarts/components";
import { use as useECharts } from "echarts/core";

import { EChartsContainer, resolveChartColor, resolveChartTheme, type ChartTheme } from "@/lib/echarts";
import { cn } from "@/lib/utils";

import type { LineChartProps, LineChartReferenceLine, LineChartSeries } from "./line-chart.types";

// ECharts registration is global and idempotent; keep the chart module set local.
// eslint-disable-next-line react-hooks/rules-of-hooks
useECharts([EChartsLineChart, GridComponent, TooltipComponent, MarkLineComponent]);

const DEFAULT_COLORS = ["var(--ks-primary)", "var(--ks-kinpaku)", "var(--ks-success)", "var(--ks-danger)"];

export function buildLineOption(
  series: LineChartSeries[],
  labels: string[] | undefined,
  options: Pick<LineChartProps, "showArea" | "showDots" | "showGrid" | "referenceLine" | "step"> & {
    theme: ChartTheme;
  }
): EChartsOption {
  const categories = labels ?? series[0]?.data.map((_, index) => String(index)) ?? [];
  const values = series.flatMap((item) => item.data);
  const palette = DEFAULT_COLORS.map((color) => resolveChartColor(color, options.theme.tokenColors));
  return {
    animation: true,
    grid: { left: 8, right: 8, top: 12, bottom: labels ? 24 : 12, containLabel: Boolean(labels) },
    xAxis: {
      type: "category",
      data: categories,
      axisLine: { lineStyle: { color: options.theme.axisColor } },
      axisTick: { show: false },
      axisLabel: { show: Boolean(labels), color: options.theme.faintTextColor, fontSize: 10 },
    },
    yAxis: {
      type: "value",
      min: Math.min(...values, 0),
      max: Math.max(...values, 1),
      splitNumber: 4,
      axisLabel: { color: options.theme.faintTextColor, fontSize: 10 },
      splitLine: { show: options.showGrid, lineStyle: { color: options.theme.axisColor } },
      axisLine: { show: false },
    },
    tooltip: { trigger: "axis" },
    series: series.map((item, index) => {
      const color = resolveChartColor(item.color ?? palette[index % palette.length], options.theme.tokenColors);
      return {
        name: item.label,
        type: "line",
        data: item.data,
        symbol: options.showDots ? "circle" : "none",
        symbolSize: options.showDots ? 6 : 0,
        showSymbol: options.showDots,
        lineStyle: { color, width: 2, join: "round" },
        itemStyle: { color },
        areaStyle: options.showArea ? { color, opacity: 0.12 } : undefined,
        step: options.step,
        markLine: index === 0 ? buildReferenceMarkLine(options.referenceLine, options.theme) : undefined,
      };
    }),
  };
}

/** markLine nativo do ECharts pra desenhar a linha de meta/media com rotulo. */
function buildReferenceMarkLine(
  referenceLine: LineChartReferenceLine | undefined,
  theme: ChartTheme
): MarkLineComponentOption | undefined {
  if (!referenceLine) return undefined;
  const color = referenceLine.color
    ? resolveChartColor(referenceLine.color, theme.tokenColors)
    : theme.mutedTextColor;
  return {
    silent: true,
    symbol: "none",
    lineStyle: { color, type: "dashed", width: 1.5 },
    label: {
      show: !!referenceLine.label,
      formatter: referenceLine.label ?? "",
      position: "end",
      color,
      fontSize: 10,
    },
    data: [{ yAxis: referenceLine.value }],
  };
}

export function LineChart({
  series,
  labels,
  height = 200,
  width = "100%",
  showArea = true,
  showDots = true,
  showGrid = true,
  showLegend = true,
  referenceLine,
  step,
  className,
  style,
}: LineChartProps) {
  const option = buildLineOption(series, labels, {
    showArea,
    showDots,
    showGrid,
    referenceLine,
    step,
    theme: resolveChartTheme(),
  });
  return (
    <div className={cn(className)} style={{ ...style, width }}>
      <EChartsContainer
        option={option}
        height={height}
        ariaLabel={`Line chart: ${series.map((item) => item.label).join(", ")}`}
      />
      {showLegend && series.length > 1 && (
        <div className="flex flex-wrap gap-x-(--spacing-lg) gap-y-(--spacing-2xs) mt-(--spacing-sm) px-(--spacing-2xs)">
          {series.map((item, index) => (
            <div key={item.label} className="flex items-center gap-(--spacing-xs)">
              <div
                suppressHydrationWarning
                className="w-6 h-[2px] rounded-full"
                style={{ background: item.color ?? DEFAULT_COLORS[index % DEFAULT_COLORS.length] }}
              />
              <span className="text-body-caption text-muted">{item.label}</span>
            </div>
          ))}
        </div>
      )}
    </div>
  );
}
